/**
 * upgrade 域 0.2.3 → 0.2.4：配置形态割接——把散在顶层的渠道开关搬进 `channels` 数组的两条内置条目。
 *
 * 为什么直接读写文件而不是走 config 域的写面：链跑在各域装配**之前**，那时写面没有装配好的配置镜像，
 * 以它当基底合并会把整份配置写空。本步只做结构搬运——读出来、换个位置、写回去——不解释语义，所以
 * 「什么算合法设置」仍旧只有 config 域归一化一个答案；它装配在本步之后，读到的正是割接后的形态。
 *
 * 幂等：条目已在场且没有存量要合并时直接返回，重跑与首次跑的结果逐字相同。
 */
import { readFileSync } from "node:fs";
import { writeTextAtomicSync, CONFIG_FILE_NAME, notifierFile } from "../../../shared/interface.ts";
import type { LegacySettingsFace, RawSettingValue } from "../../deps.ts";
import { readLegacySettings } from "../legacy/index.ts";

/**
 * 内置频道类型。这里是**升级域的清单**（旧格式里哪两个渠道要收进 `channels`），不是 config 域那份的
 * 副本：本域不认识当前设置的形状，只认识「旧文件里有哪几个顶层键、该把它们搬到哪儿」。
 */
const BUILTIN_TYPES = ["browser", "system"] as const;

/**
 * 0.2.3 及更早的顶层渠道键：值搬进内置条目之后**删除**——迁移一次做完，不留「旧键还能读」的第二处表达。
 *
 * **读面自 #1016 S3 起不再消费这些键**（实测：只带 `browserEnabled` / `notifySound` 等旧顶层键、
 * channels 里没有内置条目的配置，`normalizeConfig` 物化出来的是**默认表**那两条内置，旧值一个都没进来）。
 * 所以这一步不是「跑了更好、不跑也行」的可选优化，而是**唯一**的搬运者：没跑到时用户的旧渠道开关
 * 既没被搬进条目、又留在顶层，而写面对这些键一律 400（退役键话术，指向「刷新后重试」），此后每次
 * 保存都失败。
 *
 * 名字里带 MIGRATED 而不是复用 config 域那份 RETIRED_KEYS：两者的成员眼下重合，语义却不同——
 * 这份是「要搬到哪去」的迁移清单，config 域那份是「写面一律拒收」的退役清单（它还含没有后继键的
 * maxConnections）。合成一份会让「搬走」与「删掉」两种事实重新纠缠在一起。
 */
const MIGRATED_TOP_LEVEL_KEYS: readonly string[] = [
  "systemEnabled",
  "browserEnabled",
  "systemNotify",
  "browserNotify",
  "notifyWhenVisible",
  "notifySound",
  "browserSound",
  "systemSound",
];

type BuiltinType = (typeof BUILTIN_TYPES)[number];

/**
 * 割接：宿主 settings 里的存量与当前配置文件合并，再把顶层渠道键搬进两条内置条目。
 *
 * 合并顺序与旧写面同口径（文件为基底、存量覆盖）：「设置回到更早的样子」比「保留当前值」糟得多。
 */
export function migrateConfigShape(settings: LegacySettingsFace): void {
  const file = notifierFile(CONFIG_FILE_NAME);
  const stored = readStoredObject(file);
  const legacy = readLegacySettings(settings);
  const hasLegacy = Object.keys(legacy).length > 0;
  // 既没有文件内容也没有存量 = 全新安装：默认表就是它的形态，凭空建一份文件反而会让设置页把默认值
  // 标成「用户改过」——那正是「文件里每个键都被读成显式提交」这条既有语义的反面。
  if (!hasLegacy && Object.keys(stored).length === 0) return;
  const merged: Record<string, RawSettingValue> = { ...stored, ...legacy };
  const shaped = withBuiltinChannels(merged);
  // 有存量就必须落盘（合并结果与文件不同）；没有存量时只在真的缺内置条目时才写。
  if (!hasLegacy && shaped === null) return;
  const written = writeTextAtomicSync(file, `${JSON.stringify(shaped ?? merged, null, 2)}\n`);
  if (!written.ok) throw new Error(`dsh-notifier: 配置形态割接落盘失败 — ${written.reason}`);
}

/** 割接后的形态；`null` = 没有可搬的键、也没有可删的键（幂等出口）。 */
function withBuiltinChannels(
  stored: Record<string, RawSettingValue>,
): Record<string, RawSettingValue> | null {
  const list = Array.isArray(stored.channels) ? stored.channels : [];
  const present = new Set<RawSettingValue>();
  for (const item of list) {
    if (isRecord(item)) present.add(item.type);
  }
  const missing = BUILTIN_TYPES.filter((type) => !present.has(type));
  const retired = MIGRATED_TOP_LEVEL_KEYS.filter((key) => stored[key] !== undefined);
  if (missing.length === 0 && retired.length === 0) return null;
  // 内置恒在最前：与 config 域归一化后的顺序一致，用户看到的卡片顺序不会因为割接而变。
  const next: Record<string, RawSettingValue> = {
    ...stored,
    channels: [...missing.map((type) => builtinEntry(stored, type)), ...list],
  };
  // 搬完即删：同一个事实不留两处表达——留着旧键就成了下一个 `notifySound` 式的隐患。
  for (const key of retired) delete next[key];
  return next;
}

/** 内置条目：只搬**有值**的存量键，缺的留给 config 域归一化补默认——割接不替用户决定默认值。 */
function builtinEntry(
  stored: Record<string, RawSettingValue>,
  type: BuiltinType,
): Record<string, RawSettingValue> {
  const entry: Record<string, RawSettingValue> = { type, id: type };
  const fields: ReadonlyArray<readonly [string, RawSettingValue]> =
    type === "browser"
      ? [
          ["enabled", stored.browserEnabled],
          ["popup", stored.browserNotify],
          ["sound", firstDefined(stored.browserSound, stored.notifySound)],
          ["whenVisible", stored.notifyWhenVisible],
        ]
      : [
          ["enabled", stored.systemEnabled],
          ["popup", stored.systemNotify],
          ["sound", firstDefined(stored.systemSound, stored.notifySound)],
        ];
  for (const [key, value] of fields) {
    if (value !== undefined) entry[key] = value;
  }
  return entry;
}

/** 存量音效键的取值顺序：按出口的键优先，其次旧的全局键——与 config 域归一侧同序，两处不能各说各话。 */
function firstDefined(outlet: RawSettingValue, legacy: RawSettingValue): RawSettingValue {
  return outlet === undefined ? legacy : outlet;
}

/**
 * 配置文件 → 对象。只有文件不存在是合法空配置；存在却读不动、解析不了或顶层不是普通对象，都代表
 * 迁移基线已经不可信，必须让链失败并把刻度留在原处。
 */
function readStoredObject(file: string): Record<string, RawSettingValue> {
  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch (cause) {
    if (isMissingFile(cause)) return {};
    const detail = cause instanceof Error ? `：${cause.message}` : "";
    throw new Error(`dsh-notifier: 配置形态割接读取失败 — ${file}${detail}`, { cause });
  }

  let parsed: RawSettingValue;
  try {
    parsed = JSON.parse(text);
  } catch (cause) {
    const detail = cause instanceof Error ? `：${cause.message}` : "";
    throw new Error(`dsh-notifier: 配置形态割接解析失败 — ${file}${detail}`, { cause });
  }
  if (!isRecord(parsed)) {
    throw new Error(`dsh-notifier: 配置形态割接解析失败 — ${file}：顶层不是普通对象`);
  }
  return parsed;
}

function isMissingFile(error: unknown): boolean {
  return (
    typeof error === "object" &&
    error !== null &&
    "code" in error &&
    (error as { code?: unknown }).code === "ENOENT"
  );
}

function isRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/**
 * upgrade 域 0.2.5 → 0.2.6：免打扰多时间窗——把旧的顶层 start/end 搬进 windows[0] 并删除旧键。
 *
 * 为什么直接读写文件而不是走 config 域的写面：与 0.2.4 的配置形态割接同理，链跑在各域装配之前，
 * 那时写面没有装配好的配置镜像（见 steps/config-shape.ts 的注释）。本步只做结构搬运，不解释语义：
 * 起止是否合法由 config 域归一化在装配后判定，这里只认有没有这两个键。
 *
 * 幂等：windows 已在场、没有配置文件、没有 quietHours、旧键不全时都直接返回，重跑与首次跑的结果逐字相同。
 */
import {
  readTextFileSync,
  writeTextAtomicSync,
  CONFIG_FILE_NAME,
  notifierFile,
} from "../../../shared/interface.ts";
import type { RawSettingValue } from "../../deps.ts";

/** 旧形的两个时钟键：值搬进 windows[0] 之后删除——同一个事实不留两处表达。 */
const LEGACY_CLOCK_KEYS: readonly string[] = ["start", "end"];

/**
 * 割接：旧 start/end 搬进 windows[0] 并删除旧键。
 *
 * 只搬「两个键都在」的完整旧形：缺了一半的文件不动（读面 legacy 回落会把它看成默认窗口，
 * 而搬一半等于替用户编半个窗口——割接不替用户决定取值，见 config-shape.ts 的同款纪律）。
 */
export function migrateQuietWindows(): void {
  const file = notifierFile(CONFIG_FILE_NAME);
  const read = readTextFileSync(file);
  if (!read.ok) return;
  const stored = parseObject(read.text);
  const shaped = withQuietWindows(stored);
  // 没有活要干时一个字都不写：每次启动重写文件会把用户手改的格式重新序列化，那是静默改写而不是迁移。
  if (shaped === null) return;
  const written = writeTextAtomicSync(file, JSON.stringify(shaped, null, 2) + "\n");
  if (!written.ok) throw new Error("dsh-notifier: 免打扰多时间窗割接落盘失败 — " + written.reason);
}

/** 割接后的形态；null = 没有可搬的键（幂等出口）。 */
function withQuietWindows(
  stored: Record<string, RawSettingValue>,
): Record<string, RawSettingValue> | null {
  const quiet = stored.quietHours;
  if (!isRecord(quiet)) return null;
  if (Array.isArray(quiet.windows)) {
    // 已迁移：正常路径旧键早已删除，防的只是手改出的混合形态（windows 与旧键并存）。
    if (quiet.start === undefined && quiet.end === undefined) return null;
    const cleaned: Record<string, RawSettingValue> = { ...quiet };
    for (const key of LEGACY_CLOCK_KEYS) delete cleaned[key];
    return { ...stored, quietHours: cleaned };
  }
  if (typeof quiet.start !== "string" || typeof quiet.end !== "string") return null;
  const next: Record<string, RawSettingValue> = {
    ...quiet,
    windows: [{ start: quiet.start, end: quiet.end }],
  };
  for (const key of LEGACY_CLOCK_KEYS) delete next[key];
  return { ...stored, quietHours: next };
}

/** 文件内容 → 对象；坏 JSON 与非对象都当「没有配置」——一份读不动的文件不该让启动失败。 */
function parseObject(text: string): Record<string, RawSettingValue> {
  try {
    const parsed: RawSettingValue = JSON.parse(text);
    return isRecord(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function isRecord(raw: RawSettingValue): raw is Record<string, RawSettingValue> {
  return typeof raw === "object" && raw !== null && !Array.isArray(raw);
}

/**
 * upgrade 域 0.2.3 → 0.2.4：存储布局归位——把散在 DSH home 根目录的数据文件收进包私有目录；**没有旧文件的安装同样
 * 在这一步落定**（直接建出初始形态）。配置文件不在这里：它有两代旧形态，读取要等宿主服务就绪（装配期拿不到的时机）。
 */
import { existsSync, readFileSync, renameSync } from "node:fs";
import {
  writeTextAtomicSync,
  HISTORY_FILE_NAME,
  SEQ_FILE_NAME,
  STATUS_FILE_NAME,
  legacyFile,
  notifierFile,
} from "../../../shared/interface.ts";
/** 旧文件改名后缀：搬完留证据，也是「这一份处理过了」的标记。 */
const MIGRATED_SUFFIX = ".migrated.bak";

/** 空 JSON 对象的落盘形态。 */
const EMPTY_OBJECT = "{}\n";

/** 序号文件的初始形态：与流侧落盘同形（流侧写 `${seq}\n`），首次读取直接得到 0。 */
const ZERO_SEQ = "0\n";

/** 存储布局的一项。 */
interface StorageEntry {
  /** 旧文件名（DSH home 根目录下）。 */
  legacy: string;
  /** 新文件名（包私有存储目录下）。 */
  target: string;
  /** 目标缺失且无旧文件时的初始形态。 */
  initial: string;
}

const LAYOUT: readonly StorageEntry[] = [
  {
    legacy: "dsh-notifier-history.jsonl",
    target: HISTORY_FILE_NAME,
    initial: "",
  },
  {
    legacy: "dsh-notifier-status.json",
    target: STATUS_FILE_NAME,
    initial: EMPTY_OBJECT,
  },
  {
    legacy: "notifier-seq.json",
    target: SEQ_FILE_NAME,
    initial: ZERO_SEQ,
  },
];

/**
 * 旧存储 → 新存储布局：有旧文件的搬过来，没有的建出初始形态。初始形态一律是**空结构**而不是默认值快照
 * ——写全量默认值会把「用户覆盖过哪些键」这个语义冲掉（文件里每个键都会被读成用户显式提交的），而那份差别
 * 正是设置页判断哪些字段该标记为「已改」的依据。逐文件独立（一个搬不动不影响其余），但**搬不动都抛出**：
 * 迁移没做完而启动照常，等于让各域按错误的形态去读数据。幂等：目标已存在即处理过，归档名固定、重跑不累积。
 */
export function migrateStorageLayout(): void {
  for (const entry of LAYOUT) settleOne(entry);
}

/**
 * 落定一项。目标已存在即视为「这一份处理过了」：不覆盖、只把源文件归档——用户可能在新位置已经改过东西，
 * 用旧文件盖回去等于用历史覆盖现在。
 */
function settleOne(entry: StorageEntry): void {
  const target = notifierFile(entry.target);
  const source = legacyFile(entry.legacy);

  if (existsSync(target)) {
    archive(source, MIGRATED_SUFFIX);
    return;
  }
  if (!existsSync(source)) {
    writeTarget(target, entry.initial);
    return;
  }
  writeTarget(target, readSource(source));
  archive(source, MIGRATED_SUFFIX);
}

/** 读旧文件；读不出来即抛——那是「搬不动」，不该被当成「没有旧数据」。 */
function readSource(source: string): string {
  try {
    return readFileSync(source, "utf8");
  } catch (cause) {
    throw new Error(`旧存储文件不可读：${source}`, { cause });
  }
}

function writeTarget(target: string, text: string): void {
  const written = writeTextAtomicSync(target, text);
  if (!written.ok) throw new Error(`存储文件落盘失败：${target} — ${written.reason}`);
}

/** 归档旧文件；本来就没有就什么都不做。后缀是「这一份处理过了」的标记。 */
function archive(source: string, suffix: string): void {
  if (!existsSync(source)) return;
  try {
    renameSync(source, `${source}${suffix}`);
  } catch (cause) {
    throw new Error(`旧存储文件改名失败：${source}`, { cause });
  }
}

/**
 * upgrade 域生命周期：装配期跑完升级链。链动的是磁盘上的文件（存储三个文件 + 配置文件的形态割接），
 * 存量配置的读取面由组合根以显式依赖注入，装配期即可读——不再有「等宿主服务就绪」那段回调。
 *
 * 装配器本身在共享层（重复装配抛错、链抛错时不置标记、卸载复位三件事同构），本域只提供 label 与链。
 */
import { createUpgradeRunner } from "../../../../../../../shared/upgrade-chain.js";
import type { UpgradeDeps } from "../../deps.ts";
import { runUpgradeChain } from "../chain/index.ts";

/** 本域唯一的装配实例：闭包持有「已装配」标记，外面拿不到第二份升级流程。 */
export const upgradeRunner = createUpgradeRunner<UpgradeDeps>("dsh-notifier", runUpgradeChain);

/** upgrade 域升级链的步骤表。**新增版本时必须在此追加一项**，哪怕这一步没有数据要改（`run` 给空实现）：链的推进
 * 以步骤为刻度，漏掉的版本会让存储刻度永久停在旧值上。 */
import type { UpgradeStep } from "../../../../../../../shared/upgrade-chain.js";
import { tickUpgradeVersionSync } from "../../../../../../../shared/upgrade-tick.js";
import type { UpgradeDeps } from "../../deps.ts";
import { migrateCanonicalKeys } from "./canonical-keys.ts";
import { migrateConfigShape } from "./config-shape.ts";
import { migrateQuietWindows } from "./quiet-windows.ts";
import { migrateReasonShape } from "./reason-shape.ts";
import { migrateStorageLayout } from "./storage-layout.ts";

/** 0.2.3 → 0.2.4：存储布局归位 + 配置形态割接 + 投递理由形态割接——同一次版本迁移的三半，合成一步。 */
function migrateToNewLayout(deps: UpgradeDeps): void {
  // 顺序有意义：布局归位先建出新位置的初始形态，理由割接才有文件可读（旧位置的文件已被搬走）。
  migrateStorageLayout();
  migrateConfigShape(deps.legacySettings);
  migrateReasonShape();
}

/** 0.2.5 → 0.2.6：免打扰多时间窗（#936）——旧的 start/end 搬进 windows[0] 并删除旧键。 */
function migrateToV026(): void {
  migrateQuietWindows();
}

/** 0.2.8 → 0.2.9：配置形态清理（#1016 S3）——读面不再兜底，兜底搬到这里。
 * 形态清理不能挂 0.2.8：那一版已发布且对 notifier 是空步（dsh 0.2.0-rc.2 适配），刻度已推进过。
 */
function migrateToV029(): void {
  migrateCanonicalKeys();
}

/** 按目标版本升序维护；执行顺序由链驱动排序决定，此处顺序只为便于阅读。 */
export const STEPS: readonly UpgradeStep<UpgradeDeps>[] = [
  { fromVersion: "0.2.3", targetVersion: "0.2.4", run: migrateToNewLayout },
  // 0.2.4 → 0.2.5 为空步（客户端半区分层重构，无形态变化）：run 指共享空函数，不再为新版本加空函数。
  { fromVersion: "0.2.4", targetVersion: "0.2.5", run: tickUpgradeVersionSync },
  { fromVersion: "0.2.5", targetVersion: "0.2.6", run: migrateToV026 },
  // 0.2.6 → 0.2.7 为空步（本版不含 notifier 存储形态变化）：run 指共享空函数。
  { fromVersion: "0.2.6", targetVersion: "0.2.7", run: tickUpgradeVersionSync },
  // 0.2.7 → 0.2.8 为空步（dsh 0.2.0-rc.2 适配，无存储形态变化）：run 指共享空函数。
  { fromVersion: "0.2.7", targetVersion: "0.2.8", run: tickUpgradeVersionSync },
  // 0.2.8 → 0.2.9：配置形态清理（#1016 S3）——读面不再兜底，兜底搬到这里。
  { fromVersion: "0.2.8", targetVersion: "0.2.9", run: migrateToV029 },
];

/**
 * upgrade 域 0.2.3 → 0.2.4：投递理由形态割接——`status.json` 与 `history.jsonl` 里存的是散文，
 * 之后存结构化对象（`{ code, params?, detail? }`）。
 *
 * 为什么放在升级链里而不是让读面各判一次：这两个文件都是**整份重写**的存储，割接一次之后磁盘上
 * 只剩一种形态，客户端不必为「同一字段两种形态」写两遍渲染。读面留下的值域校验只兜手改与半截
 * 写入，不再承担「历史形态」这条主线。
 *
 * 幂等：已经是结构化对象的条目原样保留，重跑不叠加。**解析不出内容时不动那个文件**——两个存储
 * 的读面本来就容错（坏行跳过、半截 JSON 从空表开始），为一份读不出的旧文件拦住启动是更坏的结果；
 * 而写失败必须抛出，那才是「迁移没做完」（与 storage-layout 同一口径）。
 */
import { readFileSync } from "node:fs";
import {
  writeTextAtomicSync,
  HISTORY_FILE_NAME,
  STATUS_FILE_NAME,
  normalizeReason,
  notifierFile,
  sameReasonShape,
} from "../../../shared/interface.ts";

/** 形态割接的落点：文件名 + 一份「把一条记录里嵌的理由挑出来重写」的转换。 */
export function migrateReasonShape(): void {
  rewriteFile(notifierFile(STATUS_FILE_NAME), migrateStatusText);
  rewriteFile(notifierFile(HISTORY_FILE_NAME), migrateHistoryText);
}

/**
 * 读 → 转换 → 有变化才写回。
 *
 * 「只在有变化时写」不是省一次 IO：`history.jsonl` 是追加式存储，无条件重写在并发 append 时
 * 会把那一行盖掉；没有旧形态可割接时什么都不碰，是唯一不引入新竞争窗口的形态。
 */
function rewriteFile(file: string, transform: (text: string) => string | undefined): void {
  let text: string;
  try {
    text = readFileSync(file, "utf8");
  } catch {
    // 文件不存在：storage-layout 已经建出初始形态，这里没有活要干。
    return;
  }
  const migrated = transform(text);
  if (migrated === undefined || migrated === text) return;
  const written = writeTextAtomicSync(file, migrated);
  if (!written.ok) throw new Error(`投递理由割接写入失败：${file} — ${written.reason}`);
}

/** `status.json`：逐条把 `lastError` 的旧散文形态换成结构化理由，其余字段原样保留。 */
function migrateStatusText(text: string): string | undefined {
  const table = parseObject(text);
  if (table === undefined) return undefined;
  let changed = false;
  const rebuilt: Record<string, unknown> = {};
  for (const [channelId, entry] of Object.entries(table)) {
    const migrated = migrateStatusEntry(entry);
    if (migrated !== entry) changed = true;
    rebuilt[channelId] = migrated;
  }
  return changed ? `${JSON.stringify(rebuilt, null, 2)}\n` : undefined;
}

/** 单条状态：只认「有 lastError 且它不是规范化后的形态」这一种需要动的形状，其余原样返回。 */
function migrateStatusEntry(entry: unknown): unknown {
  if (typeof entry !== "object" || entry === null || Array.isArray(entry)) return entry;
  const source = entry as Record<string, unknown>;
  if (source.lastError === undefined) return entry;
  const reason = normalizeReason(source.lastError);
  if (reason === undefined) return entry;
  // 已经是同一个对象级形态（`normalizeReason` 对结构化输入是恒等语义的）就不再重写。
  if (sameReasonShape(source.lastError, reason)) return entry;
  return { ...source, lastError: reason };
}

/** `history.jsonl`：逐行换掉 `channels[].reason`，坏行原样保留（读侧本来就跳过它）。 */
function migrateHistoryText(text: string): string | undefined {
  let changed = false;
  const lines = text.split("\n").map((line) => {
    if (line === "") return line;
    const migrated = migrateHistoryLine(line);
    if (migrated === undefined) return line;
    changed = true;
    return migrated;
  });
  return changed ? lines.join("\n") : undefined;
}

function migrateHistoryLine(line: string): string | undefined {
  const entry = parseObject(line);
  if (entry === undefined) return undefined;
  const channels = entry.channels;
  if (!Array.isArray(channels)) return undefined;
  let changed = false;
  const rebuilt = channels.map((delivery) => {
    if (typeof delivery !== "object" || delivery === null || Array.isArray(delivery))
      return delivery;
    const source = delivery as Record<string, unknown>;
    if (source.reason === undefined) return delivery;
    const reason = normalizeReason(source.reason);
    if (reason === undefined || sameReasonShape(source.reason, reason)) return delivery;
    changed = true;
    return { ...source, reason };
  });
  return changed ? JSON.stringify({ ...entry, channels: rebuilt }) : undefined;
}

/** 解析成 JSON 对象；数组、标量、坏 JSON 都算读不出（调用点按此跳过而不是猜）。 */
function parseObject(text: string): Record<string, unknown> | undefined {
  try {
    const parsed = JSON.parse(text) as unknown;
    return typeof parsed === "object" && parsed !== null && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : undefined;
  } catch {
    return undefined;
  }
}

/** upgrade 域刻度落点：**存储版本**（`version` 文件里的刻度）的读写与读策略。刻度是「这一步做完了」
 * 的凭证，故读侧是 fail-closed——读不到与读坏了必须分开：只有精确 ENOENT 才回落 0.0.0 起跑，空文件、
 * 坏内容与读错误一律中止启动，把坏源伪装成全新安装比不启动糟得多。
 *
 * 插件版本（对账目标）与版本比较不在本模块：它们是跨包骨架，属 shared/upgrade-chain.js。 */
import { readFileSync } from "node:fs";
import {
  writeTextAtomicSync,
  VERSION_FILE_NAME,
  notifierFile,
  type FileWrite,
} from "../../../shared/interface.ts";

/** 没有版本文件时的起点：从未升级过。 */
const BASELINE_VERSION = "0.0.0";

/** 存储刻度只接受 v0/v1 的规范三段式；预发布、缺段、前后缀与前导零都不属于本升级链。 */
const SUPPORTED_STORED_VERSION = /^(?:0|1)\.(?:0|[1-9]\d*)\.(?:0|[1-9]\d*)$/u;

/** 读取器接缝只为稳定覆盖 Node 文件错误码；生产默认直接同步读取。 */
type ReadVersionFile = (file: string) => string;

/** 读存储版本。仅目标文件精确不存在时从零起跑；读错、空值或坏内容都必须让启动中止，不能把坏源伪装成全新安装。 */
export function readStoredVersion(
  read: ReadVersionFile = (file) => readFileSync(file, "utf8"),
): string {
  let raw: string;
  try {
    raw = read(notifierFile(VERSION_FILE_NAME));
  } catch (cause) {
    const code = errorCode(cause);
    if (code === "ENOENT") return BASELINE_VERSION;
    const reason = cause instanceof Error ? cause.message : String(cause);
    throw new Error(
      `dsh-notifier: 存储版本文件读取失败${code === undefined ? "" : `（${code}）`} — ${reason}`,
      { cause },
    );
  }

  const version = raw.trim();
  if (version === "") throw new Error("dsh-notifier: 存储版本文件为空");
  if (!SUPPORTED_STORED_VERSION.test(version)) {
    throw new Error(
      `dsh-notifier: 存储版本文件包含非法或不支持的版本号：${JSON.stringify(version)}`,
    );
  }
  return version;
}

/** 写存储版本：一步升级完成即推进一档；写不进去就停在原处，下次重跑该步。 */
export function writeStoredVersion(version: string): FileWrite {
  return writeTextAtomicSync(notifierFile(VERSION_FILE_NAME), `${version}\n`);
}

/** Node 文件错误会带稳定 code；没有 code 的异常仍按读取失败处理。 */
function errorCode(cause: unknown): string | undefined {
  if (typeof cause !== "object" || cause === null || !("code" in cause)) return undefined;
  return typeof cause.code === "string" ? cause.code : undefined;
}

packages/dsh-notifier/test/integration/r.source:
/**
 * dsh-notifier — 组合根（`src/index.ts`）的真实 cordis Context 集成测试。
 *
 * 面口径：这里测的是**宿主看见的那一面**——`apply` 收窄宿主上下文、按序装配八个域、卸载逆序释放；
 * 「按序」里唯一在运行期无观测量的那一段（升级链 await 跑完才轮到读文件的域）以源码文本先后锁定。
 * 这些行为只有放进真实 cordis 才成立：`inject` 门（未就绪不装配）、两条 waterfall 的 `prepend`
 * 链序、`{ global: true }` 的作用域过滤、`ctx.effect` 的卸载时机、`internal/service` 的晚到通知。
 * 假宿主只提供 `webServer`（组合根唯一触碰的宿主服务）与可选的 `settings`；事件总线、落盘、
 * 裁决管线全是真的——**不 mock `@deepseek-ai/cordis`**，也不用 `vi.mock`/`vi.fn`。
 *
 * 落盘隔离（红线）：config / stores / stream 的单例在**模块加载期**就用 `notifierFile()` 定死了
 * 路径，所以必须先把 `DSH_HOME` 指到 `mkdtempSync` 出的临时目录，再用**动态 `import()`** 拉组合根。
 * 写反了本节全部落盘就进真实 `~/.dsh`——那正是正在跑的 `dsh web` 的 home。
 *
 * 写队列纪律：历史与配置的落盘是 fire-and-forget（写队列是模块级字段，`release` 不清它），故每个
 * 产生落盘的用例都要等到自己那一条在磁盘上可见才算完；需要「没有新写入」这类否定判据时，用
 * `stores` 域自己的写口排一次队当**界碑**——队列串行，界碑落盘即此前排队的全部落盘。
 *
 * 时间纪律：本文件不钉系统时钟，`pollUntil` 的 deadline 读的正是 `Date.now()`，钉住它失败会从
 * 「断言红」退化成挂死。`afterEach` 仍还原一次，防将来有人在用例里钉。
 */
import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { Context } from "@deepseek-ai/cordis";
import type { Events, Fiber, ThisType as EventThis } from "@deepseek-ai/cordis";
import type { Agent } from "@deepseek-ai/dsh-agent";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import type { Session, SessionEvent } from "@deepseek-ai/dsh-session";
import type { ApprovalOutcome, ApprovalRequest } from "@deepseek-ai/dsh-user-approval";
import type {
  AskUserQuestionAnswer,
  AskUserQuestionRequest,
} from "@deepseek-ai/dsh-user-questions";

import {
  assertEventReachability,
  assertRealCordisContextSemantics,
} from "../../../../test/smoke-lib.ts";
import { DEFAULT_CONFIG } from "../../src/server/config/impl/model/index.ts";
import { pollUntil, settleMicrotasks, tempDshHome } from "../helpers.ts";

// DSH_HOME 必须先于被测模块求值：三个单例的落盘路径在构造时定下，而静态 import 会在任何语句
// 之前执行——顺序反了，本节全部落盘就写进真实 `~/.dsh`。
const home = tempDshHome();
const notifier = await import("../../src/index.ts");
const apiApi = await import("../../src/server/api/interface.ts");
const configApi = await import("../../src/server/config/interface.ts");
const sdkApi = await import("../../src/server/sdk/interface.ts");
const storesApi = await import("../../src/server/stores/interface.ts");
const sharedApi = await import("../../src/server/shared/interface.ts");

/** 本插件的落盘位置（新布局：包私有目录，见 `shared/paths.ts`）。 */
const storageDir = join(home.dir, "@wingsky-1", "dsh-notifier");
const configFile = sharedApi.notifierFile(sharedApi.CONFIG_FILE_NAME);
const historyFile = sharedApi.notifierFile(sharedApi.HISTORY_FILE_NAME);
const seqFile = sharedApi.notifierFile(sharedApi.SEQ_FILE_NAME);
const versionFile = sharedApi.notifierFile(sharedApi.VERSION_FILE_NAME);

/** 种下的那份配置的原文：否定判据用它比对「一个字节都没动过」。 */
function seededConfig(): string {
  return `${JSON.stringify(BASE_SETTINGS, null, 2)}\n`;
}

/** 宿主契约冻结的 8 条浏览器端点（客户端锁定，独立抄写才守得住改路径）。 */
const ROUTE_PATHS: readonly string[] = [
  "/api/dsh-notifier/config",
  "/api/dsh-notifier/history",
  "/api/dsh-notifier/status",
  "/api/dsh-notifier/kinds",
  "/api/dsh-notifier/test",
  "/api/dsh-notifier/health",
  "/api/dsh-notifier/diagnostics",
  "/api/dsh-notifier/events",
];

/**
 * 基础设置：系统出口整个关掉、浏览器出口只弹不响。
 *
 * 系统出口在 Linux 会真的 spawn `notify-send`——测试不该在开发机上弹通知；浏览器出口的帧则
 * 经组合根的 `FrameBus` 进 api 域的流（只写 `seq.json`），是本文件观察「帧走出去了」的唯一手段。
 * 两条内置频道的形态**显式写出来**：`enabled` 是频道唯一的投递闸门，靠 `systemNotify:false`
 * 之类的弹窗键关不掉它（那只让出口无事可做，仍会留下一条 skipped 明细）。
 * `historyMaxAgeDays` 取**非默认值**：逆序释放那条判据要一个与默认值不同的可辨读数。
 */
const BASE_SETTINGS = {
  channels: [
    {
      type: "browser",
      id: "browser",
      enabled: true,
      popup: true,
      sound: false,
      whenVisible: false,
    },
    { type: "system", id: "system", enabled: false, popup: false, sound: false },
  ],
  historyMaxAgeDays: 7,
} as const;

/** 历史行：只取本文件当判据的字段（整体比较会把域内文案变化变成假红）。 */
interface HistoryLine {
  kind?: string;
  message?: string;
  suppressed?: string;
  channels?: ReadonlyArray<{ channelId: string; status: string }>;
}

/** 磁盘上的历史记录。 */
function historyLines(): HistoryLine[] {
  let text: string;
  try {
    text = readFileSync(historyFile, "utf8");
  } catch {
    return [];
  }
  return text
    .split("\n")
    .filter(Boolean)
    .flatMap((line) => {
      try {
        return [JSON.parse(line) as HistoryLine];
      } catch {
        // 坏行不当判据，也不吞掉同行之外的记录
        return [];
      }
    });
}

/** 某一种通知落了几条。 */
function countKind(kind: string): number {
  return historyLines().filter((line) => line.kind === kind).length;
}

/** 磁盘上第一条某一种通知：`beforeEach` 清过历史，所以不受上一个用例干扰。 */
function kindLine(kind: string): HistoryLine | undefined {
  return historyLines().find((line) => line.kind === kind);
}

/** 界碑用的种类名：只出现在界碑行里，任何通知判据都不会撞上它。 */
const SENTINEL_KIND = "itest-sentinel";

/**
 * 排一次界碑并等它落盘，用来给**否定**判据划界。
 *
 * 写队列串行，界碑在磁盘上可见即此前排队的写入全部落盘；没有界碑的「没有新记录」只是抢跑得来的
 * ——它证明的是「还没写完」，不是「不会写」。
 */
async function settleHistory(): Promise<void> {
  storesApi.appendHistory({ ts: Date.now(), kind: SENTINEL_KIND, title: "界碑", message: "-" });
  await pollUntil(() => historyLines().some((line) => line.kind === SENTINEL_KIND), "界碑落盘");
}

/** 浏览器出口的序号：`seq.json` 前进一格 = 帧真的走完了 FrameBus → api 域 → 流。 */
function seqValue(): number {
  try {
    const parsed = Number.parseInt(readFileSync(seqFile, "utf8").trim(), 10);
    return Number.isFinite(parsed) ? parsed : 0;
  } catch {
    return 0;
  }
}

/**
 * 本用例的序号锚点（每轮 +1000）。
 *
 * 序号是 fire-and-forget 写，「等于锚点 +1」这类判据要挡得住上一个用例迟到的那一笔——递增的锚点
 * 让迟到的值必然小于本轮的起点，于是「文件里出现了本轮的格子」只可能由本轮自己的广播产生。
 */
let seqAnchor = 0;

function seedSeqAnchor(): void {
  seqAnchor += 1000;
  mkdirSync(dirname(seqFile), { recursive: true });
  writeFileSync(seqFile, `${seqAnchor}\n`);
}

/** 写一份设置文件（组合根装配时同步读它，故必须用同步写）。 */
function seed(settings: Record<string, unknown>): void {
  mkdirSync(dirname(configFile), { recursive: true });
  writeFileSync(configFile, `${JSON.stringify(settings, null, 2)}\n`);
}

/** 假会话日志条目：本块只读 `type` 与 `data`（与 events 域单测同一口径）。 */
function turnEndEvent(turn: number, kind: string): SessionEvent {
  return { type: "turn/end", data: { turn, reason: { kind } } } as unknown as SessionEvent;
}

/** 假 agent：只露出 events 域真的会读的几处（`id` 与 `session` 的 header / 日志快照）。 */
function fakeAgent(
  id: string,
  events: SessionEvent[] = [],
  header: Record<string, unknown> = {},
): Agent {
  return {
    id,
    session: { header, snapshotEvents: () => events },
  } as unknown as Agent;
}

/** 假会话：`session/event` 的载荷带整份会话对象，而本插件只用它的 `id`。 */
function fakeSession(id: string): Session {
  return { id } as unknown as Session;
}

/**
 * 宿主按作用域派发时传的 `this`：`agent/*` 声明的是 `Scoped<Agent>`、`session/event` 是
 * `Scoped<Session>`，而那个 brand 不是本包的依赖，故从事件签名上取 `this` 位。测试要造的正是
 * `{ [Context.filter]: … }` 这一个成员——直接抄 `Scoped<…>` 会把它变成第二份事实源。
 */
type ScopedThis<K extends keyof Events> = EventThis<Events[K]>;

/** 作用域收紧的派发载体：filter 恒假，于是**只有** `{ global: true }` 的订阅能收到。 */
function scopeRejecting<K extends keyof Events>(): ScopedThis<K> {
  return { [Context.filter]: () => false } as unknown as ScopedThis<K>;
}

/**
 * 假 settings 服务只提供 describe 低优先级兜底；正式历史来源由 upgrade 域直接读取 DSH_HOME 双文件。
 * `describe()` 在真实宿主里只列**已注册**的命名空间，所以这里的 `user` 用三种取值对应三种真实形态：
 * `undefined` = 没注册这条命名空间（新架构的常态，服务面读不到）；`{}` = 注册了但 user 层为空；有键 = 注册且用户设过。
 */
function fakeSettings(user: Record<string, unknown> | undefined): { describe: () => unknown[] } {
  return {
    describe: () => (user === undefined ? [] : [{ ns: "dsh-notifier", user }]),
  };
}

/**
 * 假宿主 webServer：只实现组合根够得着的那一面（`register`），并记下摘除时的现场。
 *
 * `failAt` 让第 N 条摘除器抛错——宿主摘路由失败是真实会发生的（路由已被别人摘掉、宿主换实现），
 * 组合根的释放壳对它的承诺是「不阻断其余」。
 */
function fakeWebServer(
  observe: () => { configDays: number; serviceAlive: boolean },
  options: { failAt?: number } = {},
) {
  const routes: WebRoute[] = [];
  const removals: Array<{ path: string; configDays: number; serviceAlive: boolean }> = [];
  const service = {
    register(route: WebRoute) {
      routes.push(route);
      return () => {
        removals.push({ path: route.path, ...observe() });
        if (removals.length === options.failAt) throw new Error(`摘除失败：${route.path}`);
      };
    },
  } as unknown as Context["webServer"];
  return { service, routes, removals };
}

/** 假宿主 agent 注册表：只实现组合根读的两处（`get` 与 `isOwnedBy`）。 */
function fakeAgents(parent: Agent, child: Agent): Context["agents"] {
  return {
    get: (id: string) => (id === parent.id ? parent : undefined),
    isOwnedBy: (id: string, owner: Agent) => id === child.id && owner === parent,
  } as unknown as Context["agents"];
}

/**
 * 日志出口：`LoggerService` 的公开扩展点，用它把 warn 收进数组。
 *
 * 为什么不读内置的 `ctx.logger.buffer`：那个出口的阈值是 INFO，warn（级别 2）落在它之外，
 * buffer 里永远看不到本文件的判据文案。阈值按 `levels.default` 给——它是出口自己的约定。
 */
function captureWarnings(root: Context): string[] {
  const warnings: string[] = [];
  root.logger.exporter({
    levels: { default: 2 },
    export: (message) => {
      if (message.type === "warn") warnings.push(String(message.args[0]));
    },
  });
  return warnings;
}

/** 一次挂载的全部观测物。 */
interface Mounted {
  readonly root: Context;
  readonly fiber: Fiber;
  readonly host: ReturnType<typeof fakeWebServer>;
  /** 宿主日志出口收到的 warn 文案（组合根只经它报错）。 */
  readonly warns: string[];
  unmount(): Promise<void>;
}

/** 已挂载但用例没显式卸载的实例：`afterEach` 兜底收掉，免得路由/心跳漏到下一个用例。 */
let live: Fiber | null = null;

/**
 * 按宿主的真实挂载顺序装配：先 provide 宿主服务，再 `ctx.plugin(插件)`。
 *
 * `settings` 是本插件的**显式依赖**（组合根的 `inject`）：宿主保证它在插件装配前就绪，所以这里
 * 总是先 provide 一个假的；`settings` 的值就是那份 0.2.3 存量命名空间的 user 层（缺省 = 有服务
 * 但没存量）。「服务没来」这条分支已不属于本插件——它变成 cordis 的 inject 门（见 inject 门用例）。
 * `services` 是其余宿主服务（如 `agents`）——装与不装是两条不同的判定路径。
 */
async function mount(options: {
  config?: { enabled?: boolean };
  settings?: Record<string, unknown>;
  services?: Record<string, unknown>;
}): Promise<Mounted> {
  const root = new Context();
  root.provide("settings", fakeSettings(options.settings));
  for (const [name, value] of Object.entries(options.services ?? {})) root.provide(name, value);
  const warns = captureWarnings(root);
  const host = fakeWebServer(() => ({
    configDays: configApi.readConfig().historyMaxAgeDays,
    serviceAlive: root.get("wingsky.notifier", false) !== undefined,
  }));
  root.provide("webServer", host.service);
  const fiber = await root.plugin(notifier, options.config);
  live = fiber;
  return {
    root,
    fiber,
    host,
    warns,
    unmount: async () => {
      live = null;
      await fiber.dispose();
    },
  };
}

/**
 * 模拟宿主内置 answerer：链上**更早注册**的那一个，它给出的判定就是这次请求的最终结果。
 * 它不调 `next()`——宿主自己的应答者拿到判定后即短路，这正是本插件必须 prepend 的理由。
 */
async function mountApprovalAnswerer(
  root: Context,
  calls: string[],
  outcome: ApprovalOutcome,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("approval/request", () => {
      calls.push("answerer");
      return Promise.resolve(outcome);
    });
  });
}

/** 同上，提问那条链上的 answerer（两条 waterfall 同构，夹具分开写以免一条覆盖另一条）。 */
async function mountQuestionAnswerer(
  root: Context,
  calls: string[],
  answer: AskUserQuestionAnswer,
): Promise<Fiber> {
  return root.plugin((ctx) => {
    ctx.on("user-questions/request", () => {
      calls.push("answerer");
      return Promise.resolve(answer);
    });
  });
}

